{"code": """"Tests for impl.to_iso_week_date (SCHED-208)."""

import pytest

import impl


def test_worked_example_2009_12_31():
    assert impl.to_iso_week_date(2009, 12, 31) == (2009, 53, 4)


def test_2021_01_01_belongs_to_week_53_of_2020():
    assert impl.to_iso_week_date(2021, 1, 1) == (2020, 53, 5)


def test_2019_12_30_belongs_to_week_1_of_2020():
    assert impl.to_iso_week_date(2019, 12, 30) == (2020, 1, 1)


def test_lower_extreme_0001_01_01():
    assert impl.to_iso_week_date(1, 1, 1) == (1, 1, 1)


def test_upper_extreme_9999_12_31():
    assert impl.to_iso_week_date(9999, 12, 31) == (9999, 52, 5)


def test_leap_year_2020_has_53_weeks():
    assert impl.to_iso_week_date(2020, 12, 31) == (2020, 53, 4)


def test_year_2021_has_only_52_weeks():
    # First Monday of week 1 of 2022 -- confirms 2021 tops out at 52.
    assert impl.to_iso_week_date(2021, 12, 31) == (2021, 52, 5)


def test_leap_day_2024_returns_week_9_thursday():
    assert impl.to_iso_week_date(2024, 2, 29) == (2024, 9, 4)


def test_leap_day_2023_raises_value_error():
    with pytest.raises(ValueError):
        impl.to_iso_week_date(2023, 2, 29)


def test_century_non_leap_1900_february_only_28_days():
    with pytest.raises(ValueError):
        impl.to_iso_week_date(1900, 2, 29)


def test_century_divisible_by_400_is_leap_2000():
    assert impl.to_iso_week_date(2000, 2, 29) == (2000, 9, 2)


def test_year_out_of_range_low_raises():
    with pytest.raises(ValueError):
        impl.to_iso_week_date(0, 1, 1)


def test_year_out_of_range_high_raises():
    with pytest.raises(ValueError):
        impl.to_iso_week_date(10000, 1, 1)


def test_month_out_of_range_raises():
    with pytest.raises(ValueError):
        impl.to_iso_week_date(2023, 13, 1)
    with pytest.raises(ValueError):
        impl.to_iso_week_date(2023, 0, 1)


def test_day_out_of_range_raises():
    with pytest.raises(ValueError):
        impl.to_iso_week_date(2023, 4, 31)  # April has 30 days
    with pytest.raises(ValueError):
        impl.to_iso_week_date(2023, 1, 0)


def test_weekday_numbering_monday_through_sunday():
    # 2023-01-02 is a Monday, 2023-01-08 is the following Sunday.
    assert impl.to_iso_week_date(2023, 1, 2)[2] == 1
    assert impl.to_iso_week_date(2023, 1, 3)[2] == 2
    assert impl.to_iso_week_date(2023, 1, 4)[2] == 3
    assert impl.to_iso_week_date(2023, 1, 5)[2] == 4
    assert impl.to_iso_week_date(2023, 1, 6)[2] == 5
    assert impl.to_iso_week_date(2023, 1, 7)[2] == 6
    assert impl.to_iso_week_date(2023, 1, 8)[2] == 7


def test_week_number_never_zero_or_out_of_bounds_across_year_boundaries():
    for year in range(2015, 2025):
        wy, wn, wd = impl.to_iso_week_date(year, 1, 1)
        assert 1 <= wn <= 53
        assert 1 <= wd <= 7
        wy2, wn2, wd2 = impl.to_iso_week_date(year, 12, 31)
        assert 1 <= wn2 <= 53
        assert 1 <= wd2 <= 7


def test_first_thursday_of_year_is_always_week_1():
    # 4 January always falls in week 1 of its own calendar year.
    for year in (2000, 2009, 2016, 2020, 2021, 2023):
        wy, wn, _ = impl.to_iso_week_date(year, 1, 4)
        assert wy == year
        assert wn == 1


def test_return_type_is_tuple_of_three_ints():
    result = impl.to_iso_week_date(2023, 6, 15)
    assert isinstance(result, tuple)
    assert len(result) == 3
    assert all(isinstance(x, int) for x in result)
